    """Look a product up in the catalogue by (accent-insensitive) name."""
    sp = t['sp']
    key = _h_norm(contains)
    m = sp[sp['name_n'] == key]
    if m.empty:
        m = sp[sp['name_n'].str.contains(key, regex=False)]
