    base = t['ton'].set_index('Mã hàng')['ĐVT'].to_dict().get(code)
    fac = {base: 1.0}
    for _, r in t['dv'][t['dv']['Mã hàng'] == code].iterrows():
        fac[r['ĐVT']] = float(r['qdoi'])
    return fac

